"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1156],{51156:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/fate.png\\"\\n          title=\\"숙명\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"창해\\"\\n          publishedDate=\\"2013-08-27\\"\\n          isbn=\\"9788979197662\\"\\n          rating=3\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n살인 사건이라는 표면적 미스터리를 따라가며, 그 이면에 숨겨진 과학 윤리의 문제를 파고든다.  \\n<br>\\n사건을 통해 초반에는 독자들에게 ```누가 범인인가```, ```어떤 트릭이 사용되었는가```에 집중하게 만든다.  \\n하지만 이야기가 흐를수록 이 사건의 본질은 단순한 범인 찾기가 아님이 명확해진다.  \\n<br>\\n살인 사건은 오히려 두 주인공의 질긴 인연과 그들 뒤에 숨겨진 거대한 비밀을 수면 위로 끌어올리기 위한 하나의 장치일 뿐이다.  \\n<br>\\n이제 문제는 두 남자를 묶고 있는 <mark>숙명</mark>이란 무엇인가로 전환된다.  \\n<br>\\n운명이라는 거대한 힘 앞에서 인간의 자유의지는 과연 존재하는가?  \\n존재한다면 그 범위는 어디까지인가라는 철학적 질문을 던진다.  \\n<br>\\n조금 억지스럽고 작위적이지만, 작가의 스타일이 분명하게 드러나는 초기 작품이다.  "}')}}]);